def solve(gin):
    g=np.array(gin); H,W=g.shape
    # separator lines: full rows/cols of a single nonzero color
    sepr_rows=[r for r in range(H) if len(set(g[r]))==1 and g[r][0]!=0]
    sepr_cols=[c for c in range(W) if len({g[r][c] for r in range(H)})==1 and g[0][c]!=0]
    # band bounds
    rb=[-1]+sepr_rows+[H]; cb=[-1]+sepr_cols+[W]
    bands=[]; 
    for a,b in zip(rb[:-1],rb[1:]):
        if b-a==4: bands.append((a,b))
    # find marker shape: 4x4 block (non-sep area) containing non-square, non-zero cells
    tmpl=None
    for bi,(ra,rb_) in enumerate(bands):
        for bj,(ca,cb_) in enumerate(bands if False else [(sepr_cols[i]+1,sepr_cols[i+1]) for i in range(len(sepr_cols))]):
            pass
    # better: iterate block positions
    blocks=[(ra,rb_,ca,cb_) for ra,rb_ in bands for ca,cb_ in [(sepr_cols[i]+1,sepr_cols[i+1]) for i in range(len(sepr_cols))]]
    for ra,rb_,ca,cb_ in blocks:
        sub=g[ra:rb_,ca:cb_]; h,w=sub.shape
        if h!=4 or w!=4: continue
        nz=(sub!=0)&(sub!=np.ones_like(sub,bool))
        # exclude uniform 2x2 squares
        cells=[(r,c) for r in range(h) for c in range(w) if sub[r,c]!=0 and (r,c)!= (1,1)]
        # template cells: nonzero cells not forming solid 2x2 square at (1,1)
        core=[(r,c) for r in range(1,3) for c in range(1,3) if sub[r,c]!=0]
        tmpl_cells=[(r,c) for r in range(h) for c in range(w) if sub[r,c]!=0 and (r,c) not in core or True]
        # marker cells = all nonzero except the solid 2x2 core (if core is exactly a 2x2 solid)
        coreset=set(core)
        tm=[(r,c,int(sub[r,c])) for r in range(h) for c in range(w) if sub[r,c]!=0 and (r,c) not in coreset]
        if tm and len(tm)>=4 and all(0<=r<h and 0<=c<w for r,c,_ in tm):
            tmpl=((r,c,v) for r,c,v in tm); break
    # find band colors: square color per band
    bandcolors=[]
    for ra,rb_ in bands:
        col=None
        for ca,cb_ in [(sepr_cols[i]+1,sepr_cols[i+1]) for i in range(len(sepr_cols))]:
            sub=g[ra:rb_,ca:cb_]
            core=[(r,c) for r in range(1,3) for c in range(1,3) if sub[r,c]==sub[1,1]]
            if len(core)==4 and sub[1,1]!=0:
                col=int(sub[1,1]); break
        bandcolors.append(col)
    out=np.zeros_like(g)
    # separators
    for r in sepr_rows: out[r,:]=g[r,0]
    for c in sepr_cols: out[:,c]=g[0,c]
    for (ra,rb_),C in zip(bands,bandcolors):
        for ca,cb_ in [(sepr_cols[i]+1,sepr_cols[i+1]) for i in range(len(sepr_cols))]:
            for dr,dc,v in tmpl:
                out[ra+dr,ca+dc]=C
    return out.tolist()

